options.systemMessage:
Eres un asistente experto en análisis de conversaciones. Analiza el historial provisto y extrae la información requerida estrictamente en formato JSON válido, sin texto adicional ni bloques de código markdown extra, siguiendo este esquema:
{
  "asunto_principal": "string",
  "puntos_clave": ["string"],
  "accion_requerida": "string"
}

parameters.jsCode:
// Obtiene los datos de ambas consultas de Airtable de forma independiente
const historial = $('cunsulta historial1').all();
const lowMemory = $('Search LowMemory').all();

return [{
  json: {
    // Lista compacta del historial (segura si está vacía)
    historial_compacto: historial.length > 0 
      ? historial.map(item => ({
          message: item.json?.fields?.message ?? null,
          response: item.json?.fields?.response ?? null,
          created_on: item.json?.fields?.created_on ?? null
        })) 
      : [],

    // Datos provenientes del registro de LowMemory (segura si está vacía)
    low_memory_data: lowMemory.length > 0 
      ? lowMemory.map(item => ({
          id: item.json?.id ?? null,
          asunto_principal: item.json?.fields?.asunto_principal ?? null,
          puntos_clave: item.json?.fields?.puntos_clave ?? null,
          accion_requerida: item.json?.fields?.accion_requerida ?? null,
          session_id: item.json?.fields?.Session_ID ?? null
        })) 
      : []
  }
}];

// Obtenemos los elementos de ambos nodos de Airtable
const historial = $('cunsulta historial').all();
const lowMemory = $('Search LowMemory').all();

return [{
  json: {
    // Compactamos el historial de los últimos minutos
    historial_compacto: historial.map(item => ({
      message: item.json.fields.message,
      response: item.json.fields.response,
      created_on: item.json.fields.created_on
    })),

    // Traemos la información previa de LowMemory
    low_memory_data: lowMemory.map(item => ({
      id: item.json.id,
      asunto_principal: item.json.fields.asunto_principal || '',
      puntos_clave: item.json.fields.puntos_clave || '',
      accion_requerida: item.json.fields.accion_requerida || ''
    }))
  }
}];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "score": {
      "type": "integer",
      "description": "Puntaje del 0 al 10 que indica qué tan útil es el documento según los criterios."
    },
    "is_useful": {
      "type": "boolean",
      "description": "True si el score es mayor o igual al umbral mínimo (ej. 7), de lo contrario false."
    },
    "reason": {
      "type": "string",
      "description": "Breve explicación de por qué se asignó este puntaje y si contiene la información esperada."
    }
  },
  "required": ["score", "is_useful", "reason"]
}
